    "question": "How do you make a dashboard people actually use?",
    "is_question": true,
    "form": "Analysis memo: Question, Data, What I did, What I found, What I would do, with Context and Appendix.",
    "object": "One packet of seven thin 3D memo leaves that separates, rearranges and reassembles throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The memo uses Rafael's confirmed working sequence, specific Helix deliverables and reporting result, and the contrast between his live Rent Map and academic capstone."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The aligned leaves place five-hour and two-hour bars on a shared zero-based scale, explaining the relationship between preparation time before and after his reporting work."
    },
    "depth": {
      "result": "pass",
      "reason": "The opening question leads through context, evidence, contribution and results to a synthesis connecting a clear question, evidence with limits and a next action."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central memo packet is a confirmed working document with meaningful sections rather than a stock emblem of an analyst."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan incorporates the corrections, preserves attribution and uncertainty, and excludes unsupported metrics and confidential artifacts."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen supplies Rafael's name, product analyst positioning, five-to-two-hour reporting proof and an immediately reachable contact action."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening line about dashboards people actually use and the concrete reporting-time comparison are accessible and professionally credible."
    }
  },
